 metrics[group]=dict(steps=len(rr),**{field:sum(x[field] for x in rr) for field in ['total_change','smooth_change','gate_change','first_order_prediction','smooth_nonlinear_residual']},positive_total_changes=sum(max(0,x['total_change']) for x in rr),positive_gate_changes=sum(max(0,x['gate_change']) for x in rr),absolute_smooth_changes=sum(abs(x['smooth_change']) for x in rr),absolute_gate_changes=sum(abs(x['gate_change']) for x in rr))
